from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_PATH = Path('/app/workspace/stat_ocr.xlsx')

PSMS = ['--psm 4', '--psm 6', '--psm 11']

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]
EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']
NUM_RE = re.compile(r'(?<![\d.])\d{1,3}(?:,\d{3})*(?:\.\d{2})(?!\d)')


def ocr_variants(image_path):
    img = Image.open(image_path)
    w, h = img.size
    gray = img.convert('L')
    ac = ImageOps.autocontrast(gray)

    variants = {
        'original': img,
        'gray_ac': ac,
        'up2_gray_ac': ImageOps.autocontrast(img.resize((w * 2, h * 2), Image.LANCZOS).convert('L')),
        'up3_gray_ac': ImageOps.autocontrast(img.resize((w * 3, h * 3), Image.LANCZOS).convert('L')),
        'otsu': ac.point(lambda p: 255 if p > 128 else 0),
        'unsharp': ac.filter(ImageFilter.UnsharpMask(radius=2, percent=150)),
    }
    for name, v in variants.items():
        for psm in PSMS:
            try:
                yield name, psm, pytesseract.image_to_string(v, config=psm)
            except Exception:
                continue


def _nums(line):
    return [m.replace(',', '') for m in NUM_RE.findall(line)]


def extract_total(text):
    lines = [l.strip() for l in text.splitlines()]
    for group in PRIORITY_KEYWORDS:
        for i, line in enumerate(lines):
            U = line.upper()
            if any(x in U for x in EXCLUSIONS):
                continue
            if not any(k in U for k in group):
                continue
            nums = _nums(line)
            if nums:
                return '{:.2f}'.format(float(nums[-1]))
            for j in range(i + 1, min(i + 3, len(lines))):
                if not lines[j]:
                    continue
                nxt = _nums(lines[j])
                if nxt:
                    return '{:.2f}'.format(float(nxt[-1]))
                break
    return None


DATE_PATTERNS = [
    (r'\b(\d{4})-(\d{1,2})-(\d{1,2})\b', ['%Y-%m-%d']),
    (r'\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b', ['%d/%m/%Y', '%m/%d/%Y', '%d-%m-%Y', '%m-%d-%Y']),
    (r'\b(\d{1,2})[/-](\d{1,2})[/-](\d{2})\b', ['%d/%m/%y', '%m/%d/%y', '%d-%m-%y', '%m-%d-%y']),
    (r'\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})\b', ['%d %b %Y', '%d %B %Y']),
    (r'\b([A-Za-z]{3,9})\s+(\d{1,2}),?\s+(\d{4})\b', ['%b %d %Y', '%B %d %Y', '%b %d, %Y', '%B %d, %Y']),
]


def extract_date(text):
    for pat, fmts in DATE_PATTERNS:
        for m in re.finditer(pat, text):
            s = m.group(0)
            for fmt in fmts:
                try:
                    return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
                except ValueError:
                    continue
    return None


def consolidate(image_path):
    total_cands = []
    date_cands = []
    for _n, _p, text in ocr_variants(image_path):
        t = extract_total(text)
        if t is not None:
            total_cands.append(t)
        d = extract_date(text)
        if d is not None:
            date_cands.append(d)
    total = Counter(total_cands).most_common(1)[0][0] if total_cands else None
    date = Counter(date_cands).most_common(1)[0][0] if date_cands else None
    return date, total


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

    files = sorted(p for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'})
    for p in files:
        date, total = consolidate(p)
        print(f'{p.name}: date={date} total={total}')
        ws.append([p.name, date, total])

    wb.save(OUT_PATH)
    print(f'Saved to {OUT_PATH}')


if __name__ == '__main__':
    main()
"}

